INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Factory-Method nur für komplexe Klassenfamilien geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für einfache Objekte nutzbar"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit der Factory-Method?', 3, '[{"text": "Standardisierte Objekterstellung", "correct": true, "because": "Kapselt Instanziierung"}, {"text": "Datenfluss steuern", "correct": false, "because": "Kein Datenfokus"}, {"text": "UI-Optimierung", "correct": false, "because": "Kein Designaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zur Factory-Method?', 5, '[{"text": "Abstrakter Creator", "correct": true, "because": "Definiert Factory-Methode"}, {"text": "Konkreter Creator", "correct": true, "because": "Erzeugt spezifische Objekte"}, {"text": "Farbanimation", "correct": false, "because": "Irrelevant"}, {"text": "Hardwareknoten", "correct": false, "because": "Kein Pattern-Teil"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Factory-Method kapselt Objekterstellung. b) Sie ersetzt Abstract Factory.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Abstract Factory für Familien"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Factory-Method?', 4, '[{"text": "Creator-Klasse", "correct": false, "because": "Definiert Erstellung"}, {"text": "Produkt-Interface", "correct": false, "because": "Standardisiert Objekte"}, {"text": "UI-Gestaltung", "correct": true, "because": "Kein Pattern-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Factory-Method auch ohne abstrakte Klasse funktioniert?', 2, '[{"text": "Ja", "correct": true, "because": "Mit Interface möglich"}, {"text": "Nein", "correct": false, "because": "Flexibel gestaltbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt der Creator in der Factory-Method?', 3, '[{"text": "Objektersteller", "correct": true, "because": "Definiert Factory-Methode"}, {"text": "Datenquelle", "correct": false, "because": "Kein Datenfokus"}, {"text": "UI-Steuerung", "correct": false, "because": "Nicht UI-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten gehören zur Factory-Method?', 5, '[{"text": "Produkt-Interface", "correct": true, "because": "Standardisiert Objekte"}, {"text": "Konkreter Creator", "correct": true, "because": "Erzeugt spezifische Objekte"}, {"text": "Datenfluss", "correct": false, "because": "Kein Pattern-Teil"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Factory-Method vereinfacht Instanziierung. b) Sie ist für dynamische Verhalten gedacht. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Dynamik ist Strategy"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Factory-Method?', 4, '[{"text": "Abstrakter Creator", "correct": false, "because": "Definiert Erstellung"}, {"text": "Konkretes Produkt", "correct": false, "because": "Ergebnis der Methode"}, {"text": "Netzwerkprotokolle", "correct": true, "because": "Kein Pattern-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Factory-Method nur für Klassenfamilien?', 2, '[{"text": "Nein", "correct": true, "because": "Auch einzelne Objekte"}, {"text": "Ja", "correct": false, "because": "Vielseitig einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Factory-Method?', 4, '[{"text": "Kapselung", "correct": true, "because": "Instanziierung getrennt"}, {"text": "Flexibilität", "correct": true, "because": "Erstellung anpassbar"}, {"text": "Datenfluss", "correct": false, "because": "Kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass die Factory-Method immer abstrakt sein muss. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Kann konkret sein"}, {"text": "Ja", "correct": false, "because": "Flexibel gestaltbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Factory-Method?', 3, '[{"text": "Erstellungsstandardisierung", "correct": true, "because": "Kern des Patterns"}, {"text": "Schnelle Ausführung", "correct": false, "because": "Struktur zählt mehr"}, {"text": "UI-Optik", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Factory-Method nutzt Polymorphismus. b) Sie erstellt mehrere Objektfamilien.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Familien sind Abstract Factory"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Szenarien profitieren von der Factory-Method?', 5, '[{"text": "Objekterstellung", "correct": true, "because": "Kapselt Instanziierung"}, {"text": "Subklassensteuerung", "correct": true, "because": "Erstellung delegierbar"}, {"text": "Datenkompression", "correct": false, "because": "Kein Fokus"}, {"text": "UI-Animation", "correct": false, "because": "Kein UI-Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Factory-Method unwichtig?', 3, '[{"text": "Produkt-Interface", "correct": false, "because": "Standardisiert Objekte"}, {"text": "Creator-Klasse", "correct": false, "because": "Erzeugt Objekte"}, {"text": "Blinkende Anzeige", "correct": true, "because": "Kein Pattern-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann die Factory-Method auch statische Methoden nutzen?', 3, '[{"text": "Ja", "correct": true, "because": "Statische Factory möglich"}, {"text": "Nein", "correct": false, "because": "Flexibel gestaltbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Factory-Method für Tests hilft?', 2, '[{"text": "Ja", "correct": true, "because": "Mock-Objekte erzeugbar"}, {"text": "Nein", "correct": false, "because": "Testbarkeit fördernd"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element wähle ich für die Factory-Method?', 4, '[{"text": "Abstrakte Methode", "correct": true, "because": "Definiert Erstellung"}, {"text": "Datenfluss", "correct": false, "because": "Kein Pattern-Teil"}, {"text": "UI-Komponente", "correct": false, "because": "Nicht UI-spezifisch"}]');
